@Prosa.Util.Bigcat.bigcat_nat_uniq : ∀ {T : Type u_1} [DecidableEq T] (f : ℕ → List T),
  (∀ (i : ℕ), (f i).Nodup) →
    (∀ (x : T) (i₁ i₂ : ℕ), x ∈ f i₁ → x ∈ f i₂ → i₁ = i₂) → ∀ (n₁ n₂ : ℕ), (Prosa.Util.Notation.bigCat n₁ n₂ f).Nodup

@Prosa.Util.Bigcat.bigcat_nat_filter_eq_filter_bigcat_nat : ∀ {X : Type u_1} (F : ℕ → List X) (P : X → Bool)
  (t₁ t₂ : ℕ),
  List.filter P (Prosa.Util.Notation.bigCat t₁ t₂ F) = Prosa.Util.Notation.bigCat t₁ t₂ fun t => List.filter P (F t)

@Prosa.Util.Bigcat.bigcat_filter_eq_filter_bigcat : ∀ {X : Type u_1} {Y : Type u_2} [DecidableEq X] [DecidableEq Y]
  (f : X → List Y) (xss : List X) (P : Y → Bool),
  List.filter P (Prosa.Util.Bigcat.bigCatSeqAll xss f) = Prosa.Util.Bigcat.bigCatSeqAll xss fun x => List.filter P (f x)

@Prosa.Util.Bigcat.seq_different_elements_nil : ∀ {X : Type u_1} {Y : Type u_2} [inst : DecidableEq X] [DecidableEq Y]
  (f : X → List Y) (g : Y → X),
  (∀ (x : X), ∀ y ∈ f x, g y = x) → ∀ (x₁ x₂ : X), x₁ ≠ x₂ → List.filter (fun x => decide (g x = x₂)) (f x₁) = []
